def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        if history[0][1] == 'D':
            return 'D'
        return 'C'
    if n == 2:
        opp = [history[i][1] for i in range(n)]
        my = [history[i][0] for i in range(n)]
        if opp[0] == 'D' and opp[1] == 'C':
            return 'D'
        if opp[0] == 'C' and opp[1] == 'D':
            return 'D'
        if opp[0] == 'D' and opp[1] == 'D':
            return 'D'
        return 'C'
    opp_hist = [history[i][1] for i in range(n)]
    my_hist = [history[i][0] for i in range(n)]
    last_opp = opp_hist[-1]
    last_my = my_hist[-1]
    if n >= 4:
        last_four_opp = opp_hist[-4:]
        if last_four_opp == ['D', 'D', 'D', 'D']:
            return 'D'
    if n >= 3:
        last_three_opp = opp_hist[-3:]
        if last_three_opp == ['C', 'C', 'C'] and last_my == 'C':
            return 'C'
    if n >= 2:
        if opp_hist[-1] == 'D' and opp_hist[-2] == 'D':
            return 'D'
    def opp_coop_rate(start, end):
        if end <= start:
            return 1.0
        seg = opp_hist[start:end]
        return sum(1 for a in seg if a == 'C') / len(seg)
    recent_rate = opp_coop_rate(max(0, n - 10), n)
    overall_rate = opp_coop_rate(0, n)
    if n >= 10:
        if recent_rate < 0.2:
            return 'D'
        if recent_rate > 0.8 and overall_rate > 0.6:
            return 'C'
    if last_opp == 'C':
        if last_my == 'D':
            if rng.random() < 0.15:
                return 'D'
            return 'C'
        if n >= 3 and opp_hist[-2] == 'D' and opp_hist[-1] == 'C':
            return 'C'
        return 'C'
    else:
        if n >= 2 and opp_hist[-2] == 'C' and opp_hist[-1] == 'D':
            return 'D'
        if n >= 3 and opp_hist[-2] == 'D' and opp_hist[-3] == 'C':
            return 'D'
        if rng.random() < 0.9:
            return 'D'
        return 'C'
